package org.agentfrc.lesson;
import static org.junit.jupiter.api.Assertions.*;import java.nio.file.*;import java.util.*;import java.security.*;import org.junit.jupiter.api.*;import edu.wpi.first.hal.HAL;import edu.wpi.first.wpilibj.simulation.*;
class SeasonRollerTest {
 static Path root;static List<SeasonRollerRig.Config> configs=new ArrayList<>();static Map<Integer,String> hashes=new TreeMap<>();
 static String sha(byte[] b)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(b));}
 static double d(Properties p,String k){return Double.parseDouble(p.getProperty(k));}
 @BeforeAll static void setup()throws Exception{assertTrue(HAL.initialize(500,0));assertNotNull(System.getenv("FRC_SEASON_IO_ROOT"));root=Path.of(System.getenv("FRC_SEASON_IO_ROOT"));Properties index=new Properties();index.load(Files.newInputStream(root.resolve("index.properties")));for(String year:index.getProperty("years").split(",")){int y=Integer.parseInt(year);byte[] raw=Files.readAllBytes(root.resolve(year+"/io.properties"));hashes.put(y,sha(raw));Properties p=new Properties();p.load(new java.io.ByteArrayInputStream(raw));assertEquals("frc-season-io-input/v1",p.getProperty("schema"));assertEquals("blocked",p.getProperty("engineeringAcceptance"));assertEquals(p.getProperty("nativePropertiesSha256"),sha(Files.readAllBytes(root.resolve(year+"/native/properties.json"))));assertEquals(p.getProperty("cadSha256"),sha(Files.readAllBytes(root.resolve(year+"/native/mechanism.step"))));configs.add(new SeasonRollerRig.Config(y,p.getProperty("type"),d(p,"mass"),d(p,"radius"),d(p,"inertia"),d(p,"gear"),Integer.parseInt(p.getProperty("motors")),d(p,"outer"),d(p,"inner"),d(p,"length"),d(p,"window"),d(p,"start"),d(p,"normal"),d(p,"mu"),d(p,"beam")));}assertFalse(configs.isEmpty());}
 @BeforeEach void enable(){DriverStationSim.resetData();DriverStationSim.setDsAttached(true);DriverStationSim.setEnabled(true);DriverStationSim.notifyNewData();}
 @AfterEach void disable(){DriverStationSim.setEnabled(false);DriverStationSim.notifyNewData();RoboRioSim.setVInVoltage(12);}
 static SeasonRollerRig.Config friction(SeasonRollerRig.Config c,double mu){return new SeasonRollerRig.Config(c.season(),c.type(),c.mass(),c.radius(),c.inertia(),c.gear(),c.motors(),c.outer(),c.inner(),c.length(),c.window(),c.start(),c.normal(),mu,c.beam());}
 @Test void analyticImpulseAndSignedSharedSupply(){var c=new PrescribedRollerContact(.2,.05,.001,1,10);var r=c.resolve(0,1,1,.001);assertEquals(.004,r.leftImpulse(),1e-12);assertEquals(.04,r.velocity(),1e-12);assertEquals(.8,r.leftOmega(),1e-12);assertEquals(.0002,r.lossJ(),1e-12);var s=SharedSupply.solve(12,.02,new double[]{-.2,.2},new double[]{-1,1},new double[]{.1,.1});double expected=(12+.02*4)/(1+.02*.8);assertEquals(expected,s.volts(),1e-12);assertTrue(s.armatureAmps()[0]<0&&s.armatureAmps()[1]>0&&s.batteryAmps()>0);}
 @Test void idealShapeRaysPreserveHoleAndDeterministicTangency(){for(var c:configs){assertTrue(SeasonRollerRig.occupied(c,c.beam()+ (c.type().equals("CORAL")?c.length()/2:c.outer())));assertFalse(SeasonRollerRig.occupied(c,c.beam()+1));assertEquals(!c.type().equals("NOTE"),SeasonRollerRig.occupied(c,c.beam()));}}
 static List<SeasonRollerRig.Sample> run(SeasonRollerRig.Config c,int n,double scale,int fault){var list=new ArrayList<SeasonRollerRig.Sample>();try(var rig=new SeasonRollerRig(c,scale,fault)){for(int i=0;i<150;i++)list.add(rig.step(true,n));}return list;}
 @Test void nativeSeasonTransportThroughActualIoAndRefinement()throws Exception{Properties binding=new Properties();binding.setProperty("controllerClassSha256",sha(SeasonRollerController.class.getResourceAsStream("SeasonRollerController.class").readAllBytes()));binding.setProperty("engineeringAcceptance","blocked");binding.setProperty("score","unsupported");for(var c:configs){var a=run(c,20,1,0);var b=run(c,40,1,0);var last=a.get(149);assertTrue(last.done(),c.type()+" did not complete ideal beam sequence");assertFalse(last.timeout(),"Completion and fault must be mutually exclusive");assertEquals(c.type().equals("NOTE")?2:1,last.pulses());assertTrue(last.x()>c.beam());double dx=0,dv=0,dw=0,db=0,di=0;StringBuilder csv=new StringBuilder("tick,xM,vMps,topRadps,bottomRadps,busV,batteryA,forceN,mechanicalResidual,exitRayBlocked,pulses,beamSequenceComplete\n");for(int i=0;i<a.size();i++){var s=a.get(i);dx=Math.max(dx,Math.abs(s.x()-b.get(i).x()));dv=Math.max(dv,Math.abs(s.velocity()-b.get(i).velocity()));dw=Math.max(dw,Math.max(Math.abs(s.topOmega()-b.get(i).topOmega()),Math.abs(s.bottomOmega()-b.get(i).bottomOmega())));db=Math.max(db,Math.abs(s.bus()-b.get(i).bus()));di=Math.max(di,Math.abs(s.amps()-b.get(i).amps()));assertEquals(0,s.mechanicalResidual(),1e-6);assertTrue(Math.abs(s.force())<=2*c.mu()*c.normal()+1e-8);csv.append(i).append(',').append(s.x()).append(',').append(s.velocity()).append(',').append(s.topOmega()).append(',').append(s.bottomOmega()).append(',').append(s.bus()).append(',').append(s.amps()).append(',').append(s.force()).append(',').append(s.mechanicalResidual()).append(',').append(s.beam()).append(',').append(s.pulses()).append(',').append(s.done()).append('\n');}assertTrue(dx<.05&&dv<.05&&dw<5&&db<.2&&di<10,"Development convergence domain");Files.writeString(root.resolve(c.season()+"/transport.csv"),csv,StandardOpenOption.CREATE_NEW);binding.setProperty(c.season()+".inputSha256",hashes.get(c.season()));binding.setProperty(c.season()+".maxPositionDifferenceM",Double.toString(dx));binding.setProperty(c.season()+".maxVelocityDifferenceMps",Double.toString(dv));binding.setProperty(c.season()+".maxRotorDifferenceRadps",Double.toString(dw));binding.setProperty(c.season()+".maxBusDifferenceV",Double.toString(db));binding.setProperty(c.season()+".maxCurrentDifferenceA",Double.toString(di));}try(var stream=Files.newOutputStream(root.resolve("io-result.properties"),StandardOpenOption.CREATE_NEW)){binding.store(stream,"Prescribed contact; no real grip or score acceptance");}}
 @Test void zeroFrictionCannotTransportOrComplete(){for(var c:configs){var a=run(friction(c,0),20,1,0);var s=a.get(149);assertEquals(c.start(),s.x(),1e-12);assertFalse(s.done());assertTrue(s.timeout());}}
 @Test void signedEncoderCorruptionIsObservableAndInhibits(){for(var c:configs){var a=run(c,20,-1,0);assertTrue(a.stream().anyMatch(s->s.timeout()));assertFalse(a.get(149).done());}}
 @Test void missingOrStuckBeamCannotComplete(){try(var controller=new SeasonRollerController(.05,1)){var signal=new DIOSim(6);signal.setValue(false);controller.periodic(true);assertTrue(controller.timedOut());signal.setValue(true);controller.periodic(true);signal.setValue(false);controller.periodic(true);signal.setValue(true);controller.periodic(true);assertFalse(controller.done(),"Later beam events cannot clear a latched fault");assertTrue(controller.timedOut());}for(var c:configs)for(int fault:new int[]{1,2}){var s=run(c,20,1,fault).get(149);assertFalse(s.done());assertTrue(s.timeout());}}
 @Test void disableZerosActualOutputsWithoutClaimingPhysicalStop(){for(var c:configs)try(var rig=new SeasonRollerRig(c,1,0)){for(int i=0;i<5;i++)rig.step(true,20);var s=rig.step(false,20);assertEquals(0,s.amps(),1e-10);assertFalse(s.done());}}
 @Test void unknownInputsAndUnsupportedRegenerationReject(){assertThrows(IllegalArgumentException.class,()->new PrescribedRollerContact(.2,.05,.001,Double.NaN,5));assertThrows(IllegalArgumentException.class,()->SharedSupply.solve(12,.02,new double[]{-.1},new double[]{-4},new double[]{.1}));}
}
